CREATE TYPE "SmtpSecurityMode" AS ENUM ('IMPLICIT_TLS', 'STARTTLS');
CREATE TYPE "SmtpConfigurationLifecycle" AS ENUM ('DRAFT', 'VALIDATED', 'TESTED', 'REVOKED');

CREATE TABLE "SmtpConfigurationVersion" (
  "id" UUID NOT NULL,
  "version" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "lifecycle" "SmtpConfigurationLifecycle" NOT NULL DEFAULT 'DRAFT',
  "host" TEXT NOT NULL,
  "port" INTEGER NOT NULL,
  "securityMode" "SmtpSecurityMode" NOT NULL,
  "username" TEXT NOT NULL,
  "encryptedPassword" BYTEA NOT NULL,
  "encryptionKeyId" TEXT NOT NULL,
  "senderEmail" TEXT NOT NULL,
  "senderDisplayName" TEXT NOT NULL,
  "revision" INTEGER NOT NULL DEFAULT 1,
  "structurallyValidatedAt" TIMESTAMP(3),
  "connectionTestedAt" TIMESTAMP(3),
  "connectionTestSucceeded" BOOLEAN,
  "connectionTestResultCode" TEXT,
  "restrictedTestEmailSentAt" TIMESTAMP(3),
  "restrictedTestEmailAddress" TEXT,
  "firstActivatedAt" TIMESTAMP(3),
  "lastActivatedAt" TIMESTAMP(3),
  "createdByUserId" UUID,
  "activatedByUserId" UUID,
  "revokedAt" TIMESTAMP(3),
  "revokedByUserId" UUID,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "SmtpConfigurationVersion_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "SmtpConfigurationVersion_version_check" CHECK ("version" >= 1),
  CONSTRAINT "SmtpConfigurationVersion_revision_check" CHECK ("revision" >= 1),
  CONSTRAINT "SmtpConfigurationVersion_port_check" CHECK ("port" BETWEEN 1 AND 65535),
  CONSTRAINT "SmtpConfigurationVersion_security_port_check" CHECK (
    ("securityMode" = 'IMPLICIT_TLS' AND "port" = 465) OR
    ("securityMode" = 'STARTTLS' AND "port" = 587)
  ),
  CONSTRAINT "SmtpConfigurationVersion_required_text_check" CHECK (
    LENGTH(BTRIM("host")) > 0 AND
    LENGTH(BTRIM("username")) > 0 AND
    LENGTH(BTRIM("encryptionKeyId")) > 0 AND
    LENGTH(BTRIM("senderEmail")) > 0 AND
    LENGTH(BTRIM("senderDisplayName")) > 0 AND
    OCTET_LENGTH("encryptedPassword") > 0
  ),
  CONSTRAINT "SmtpConfigurationVersion_connection_test_check" CHECK (
    ("connectionTestedAt" IS NULL AND "connectionTestSucceeded" IS NULL AND "connectionTestResultCode" IS NULL) OR
    ("connectionTestedAt" IS NOT NULL AND "connectionTestSucceeded" IS NOT NULL AND LENGTH(BTRIM("connectionTestResultCode")) > 0)
  ),
  CONSTRAINT "SmtpConfigurationVersion_test_email_check" CHECK (
    ("restrictedTestEmailSentAt" IS NULL AND "restrictedTestEmailAddress" IS NULL) OR
    ("restrictedTestEmailSentAt" IS NOT NULL AND LENGTH(BTRIM("restrictedTestEmailAddress")) > 0)
  ),
  CONSTRAINT "SmtpConfigurationVersion_activation_check" CHECK (
    ("firstActivatedAt" IS NULL AND "lastActivatedAt" IS NULL AND "activatedByUserId" IS NULL) OR
    ("firstActivatedAt" IS NOT NULL AND "lastActivatedAt" IS NOT NULL AND "lastActivatedAt" >= "firstActivatedAt")
  ),
  CONSTRAINT "SmtpConfigurationVersion_revocation_check" CHECK (
    ("lifecycle" = 'REVOKED' AND "revokedAt" IS NOT NULL) OR
    ("lifecycle" <> 'REVOKED' AND "revokedAt" IS NULL AND "revokedByUserId" IS NULL)
  ),
  CONSTRAINT "SmtpConfigurationVersion_lifecycle_evidence_check" CHECK (
    ("lifecycle" = 'DRAFT') OR
    ("lifecycle" IN ('VALIDATED', 'TESTED', 'REVOKED') AND "structurallyValidatedAt" IS NOT NULL)
  ),
  CONSTRAINT "SmtpConfigurationVersion_tested_evidence_check" CHECK (
    "lifecycle" <> 'TESTED' OR
    ("connectionTestedAt" IS NOT NULL AND "connectionTestSucceeded" = TRUE)
  )
);

CREATE TABLE "PlatformEmailSettings" (
  "id" UUID NOT NULL,
  "scope" TEXT NOT NULL DEFAULT 'PLATFORM',
  "enabled" BOOLEAN NOT NULL DEFAULT FALSE,
  "activeConfigurationVersionId" UUID,
  "revision" INTEGER NOT NULL DEFAULT 1,
  "updatedByUserId" UUID,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "PlatformEmailSettings_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "PlatformEmailSettings_scope_check" CHECK ("scope" = 'PLATFORM'),
  CONSTRAINT "PlatformEmailSettings_revision_check" CHECK ("revision" >= 1),
  CONSTRAINT "PlatformEmailSettings_enabled_configuration_check" CHECK (NOT "enabled" OR "activeConfigurationVersionId" IS NOT NULL)
);

CREATE UNIQUE INDEX "SmtpConfigurationVersion_version_key" ON "SmtpConfigurationVersion"("version");
CREATE INDEX "SmtpConfigurationVersion_lifecycle_createdAt_idx" ON "SmtpConfigurationVersion"("lifecycle", "createdAt");
CREATE INDEX "SmtpConfigurationVersion_createdByUserId_idx" ON "SmtpConfigurationVersion"("createdByUserId");
CREATE INDEX "SmtpConfigurationVersion_activatedByUserId_idx" ON "SmtpConfigurationVersion"("activatedByUserId");
CREATE INDEX "SmtpConfigurationVersion_revokedByUserId_idx" ON "SmtpConfigurationVersion"("revokedByUserId");
CREATE UNIQUE INDEX "PlatformEmailSettings_scope_key" ON "PlatformEmailSettings"("scope");
CREATE UNIQUE INDEX "PlatformEmailSettings_activeConfigurationVersionId_key" ON "PlatformEmailSettings"("activeConfigurationVersionId");
CREATE INDEX "PlatformEmailSettings_updatedByUserId_idx" ON "PlatformEmailSettings"("updatedByUserId");

ALTER TABLE "SmtpConfigurationVersion"
  ADD CONSTRAINT "SmtpConfigurationVersion_createdByUserId_fkey"
  FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE,
  ADD CONSTRAINT "SmtpConfigurationVersion_activatedByUserId_fkey"
  FOREIGN KEY ("activatedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE,
  ADD CONSTRAINT "SmtpConfigurationVersion_revokedByUserId_fkey"
  FOREIGN KEY ("revokedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "PlatformEmailSettings"
  ADD CONSTRAINT "PlatformEmailSettings_activeConfigurationVersionId_fkey"
  FOREIGN KEY ("activeConfigurationVersionId") REFERENCES "SmtpConfigurationVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  ADD CONSTRAINT "PlatformEmailSettings_updatedByUserId_fkey"
  FOREIGN KEY ("updatedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

CREATE FUNCTION "enforce_smtp_configuration_activation"() RETURNS trigger AS $$
BEGIN
  IF NEW."activeConfigurationVersionId" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "SmtpConfigurationVersion"
    WHERE "id" = NEW."activeConfigurationVersionId"
      AND "lifecycle" = 'TESTED'
      AND "firstActivatedAt" IS NOT NULL
      AND "revokedAt" IS NULL
  ) THEN
    RAISE EXCEPTION 'Active SMTP configuration must be tested, activated, and not revoked' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "PlatformEmailSettings_active_configuration_guard"
BEFORE INSERT OR UPDATE OF "activeConfigurationVersionId" ON "PlatformEmailSettings"
FOR EACH ROW EXECUTE FUNCTION "enforce_smtp_configuration_activation"();

CREATE FUNCTION "enforce_smtp_configuration_actor_evidence"() RETURNS trigger AS $$
BEGIN
  IF NEW."firstActivatedAt" IS NOT NULL
    AND (TG_OP = 'INSERT' OR OLD."firstActivatedAt" IS NULL)
    AND NEW."activatedByUserId" IS NULL THEN
    RAISE EXCEPTION 'SMTP configuration activation requires an actor' USING ERRCODE = '23514';
  END IF;
  IF NEW."lifecycle" = 'REVOKED'
    AND (TG_OP = 'INSERT' OR OLD."lifecycle" <> 'REVOKED')
    AND NEW."revokedByUserId" IS NULL THEN
    RAISE EXCEPTION 'SMTP configuration revocation requires an actor' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "SmtpConfigurationVersion_actor_evidence_guard"
BEFORE INSERT OR UPDATE ON "SmtpConfigurationVersion"
FOR EACH ROW EXECUTE FUNCTION "enforce_smtp_configuration_actor_evidence"();

CREATE FUNCTION "enforce_activated_smtp_configuration_immutability"() RETURNS trigger AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "PlatformEmailSettings"
    WHERE "activeConfigurationVersionId" = OLD."id"
  ) AND (NEW."lifecycle" <> 'TESTED' OR NEW."revokedAt" IS NOT NULL) THEN
    RAISE EXCEPTION 'Active SMTP configuration cannot be invalidated or revoked' USING ERRCODE = '23514';
  END IF;
  IF OLD."firstActivatedAt" IS NOT NULL AND (
    NEW."host" IS DISTINCT FROM OLD."host" OR
    NEW."port" IS DISTINCT FROM OLD."port" OR
    NEW."securityMode" IS DISTINCT FROM OLD."securityMode" OR
    NEW."username" IS DISTINCT FROM OLD."username" OR
    NEW."encryptedPassword" IS DISTINCT FROM OLD."encryptedPassword" OR
    NEW."encryptionKeyId" IS DISTINCT FROM OLD."encryptionKeyId" OR
    NEW."senderEmail" IS DISTINCT FROM OLD."senderEmail" OR
    NEW."senderDisplayName" IS DISTINCT FROM OLD."senderDisplayName" OR
    NEW."version" IS DISTINCT FROM OLD."version"
  ) THEN
    RAISE EXCEPTION 'Activated SMTP configuration content is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "SmtpConfigurationVersion_activated_immutability_guard"
BEFORE UPDATE ON "SmtpConfigurationVersion"
FOR EACH ROW EXECUTE FUNCTION "enforce_activated_smtp_configuration_immutability"();
